            List<Integer> all=new ArrayList<>();for(int[] a:new int[][]{s.addresses,s.extraAddresses,s.fields,s.effectAddresses})for(int at:a)all.add(at);for(int a:all){try{readInt(a);continue;}catch(IOException missing){}final byte[] b=new byte[4];memory.bind(a,4,new Pc1NativeMemory.Region(){public int read(int at){return b[at]&255;}public void write(int at,int v){b[at]=(byte)v;}});}
