        public int read(int at)throws IOException{return memory.readAddress(at);}
        public void write(int at,int v)throws IOException{memory.writeAddress(at,v&255);}
        public int readInt(int at)throws IOException{return ui.readInt(at);}
        public void writeInt(int at,int v)throws IOException{ui.writeInt(at,v);}
        public void writeByte(int at,int v)throws IOException{write(at,v);}
        private int pixel()throws IOException{Pc1Raster.Clip r=compositor.clip();return r.left>=r.right||r.top>=r.bottom?-1:compositor.rgb(compositor.activeTarget()).rgb(r.left,r.top);}
        private String stamp()throws IOException{Pc1Raster.Clip r=compositor.clip();return compositor.activeTarget()+","+r.left+","+r.top+","+r.right+","+r.bottom+","+pixel();}
        private void mutate(String leaf)throws IOException{if(pixels){Pc1Raster.Clip r=compositor.clip();if(r.left<r.right&&r.top<r.bottom){int color=leaf.equals("effect1")?0xa10b07:leaf.equals("effect0")?0xc01f0f:leaf.equals("journal")?0x453b09:leaf.equals("inline")?0x527a24:leaf.equals("raw")?0x467879:leaf.equals("range")?0x936547:0x213456;compositor.fill(r.left,r.top,r.left+1,r.top+1,color);}}int[][] w=writes.get(leaf);if(w!=null)for(int[] row:w)writeInt(row[0],row[1]);}
        public void effects(int layer)throws IOException{if(realEffects){effects.drawLayer(layer);return;}events.add("effect,"+layer+","+stamp());mutate("effect"+layer);}
        public void glyphJournal(int first)throws IOException{events.add("journal,"+first+","+stamp());mutate("journal");}
        public void rangeButton(int button,int state)throws IOException{events.add("range,"+button+","+state+","+stamp());mutate("range");}
        public void expand(int source,int destination)throws IOException{byte[] value=ui.cstring(source),expanded=new byte[value.length+3];expanded[0]='E';expanded[1]='X';expanded[2]='P';System.arraycopy(value,0,expanded,3,value.length);ui.cstring(destination,expanded);write(destination+expanded.length+1,0);events.add("expand,"+source+","+destination);mutate("expand");}
        private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b){if(v==0)break;s.append(String.format("%02x",v&255));}return s.toString();}
        public void inline(int x,int y,int pitch,byte[] raw,int style)throws IOException{inlineBackings.add(raw.clone());events.add("inline,"+x+","+y+","+pitch+","+style+","+hex(raw)+","+stamp());mutate("inline");}
        public void rawGlyph28(int x,int y,byte[] raw,int palette)throws IOException{rawBackings.add(raw.clone());events.add("raw,"+x+","+y+","+palette+","+hex(raw)+","+stamp());mutate("raw");}
