        void compare(Snapshot s,String name)throws IOException{
            check(Arrays.equals(frame.bytes(),s.frame),"Whole native frame "+name+diff(frame.bytes(),s.frame));check(Arrays.equals(code.rawSlice(0,s.code.length),s.code),"Whole mutable code "+name);for(Region[] rr:new Region[][]{s.regions,s.templates,s.effects})for(Region r:rr){byte[] a=ui.bytes(r.address,r.bytes.length);check(Arrays.equals(a,r.bytes),"Whole native/stale byte owner "+Integer.toHexString(r.address)+" "+name+diff(a,r.bytes));}for(int n=0;n<s.addresses.length;n++)check(readInt(s.addresses[n])==s.values[n],"UI scalar "+name);for(int n=0;n<s.extraAddresses.length;n++)check(readInt(s.extraAddresses[n])==s.extraValues[n],"Graphics scalar "+name);for(int n=0;n<s.fields.length;n++)check(readInt(s.fields[n])==s.fieldValues[n],"Redraw borrowed field "+Integer.toHexString(s.fields[n])+" "+name+" actual="+readInt(s.fields[n])+" expected="+s.fieldValues[n]);for(int n=0;n<s.effectAddresses.length;n++)check(readInt(s.effectAddresses[n])==s.effectValues[n],"Effect borrowed field "+name);
            check(Arrays.equals(clip(compositor.clip()),s.clip),"Current clip "+name+Arrays.toString(clip(compositor.clip()))+" != "+Arrays.toString(s.clip));check(Arrays.equals(clip(compositor.baseClip()),s.base),"Base clip "+name);Pc1Raster.Rect r=compositor.rawDirty();check(Arrays.equals(new int[]{r.left,r.top,r.right,r.bottom},s.dirty),"Dirty "+name);check(compositor.activeTarget()==s.active,"Target "+name);for(Image i:s.images){byte[] a=i.format==0?compositor.rgb(i.handle).bgr24():compositor.alpha(i.handle).abgr32();check(Arrays.equals(a,i.bytes),"Complete image/padding "+i.handle+" "+name+diff(a,i.bytes));}List<Pc1Compositor.Invalidation> invalidations=compositor.invalidations();check(invalidations.size()==s.journal.length,"Invalidate count "+name);for(int n=0;n<s.journal.length;n++){Pc1Compositor.Invalidation e=invalidations.get(n);Pc1Raster.Rect q=e.rectangle;check(Arrays.equals(new long[]{e.serial,e.target,q.left,q.top,q.right,q.bottom},s.journal[n]),"Invalidate rectangle/order "+name);}check(normalEvents.equals(s.events),"Actual native cursor/UI service order "+name);check(events.equals(s.generalEvents),"Redraw service args/clip/pixels/order "+name+"\nactual="+events+"\nexpected="+s.generalEvents);check(effectEvents.equals(s.effectEvents),"Effect backend order "+name);check(rng==s.rng&&rngCalls==s.rngCalls,"Same shared CRT sequence "+name);
            check(inlineBackings.size()==s.inlineBackings.length&&rawBackings.size()==s.rawBackings.length,"Known raw-source call count "+name);for(int n=0;n<s.inlineBackings.length;n++)check(Arrays.equals(inlineBackings.get(n),s.inlineBackings[n]),"Full shared/local inline backing including stale suffix "+name);for(int n=0;n<s.rawBackings.length;n++)check(Arrays.equals(rawBackings.get(n),s.rawBackings[n]),"Exact cursor raw glyph source "+name);check(readInt(0xbb8458)==s.storyFlag,"Story extra flag "+name);check(storyEvents.equals(s.storyEvents),"Story leaf order/raw owner observation "+name+" actual="+storyEvents+" expected="+s.storyEvents);
        }
