    public static int run()throws Exception{
        assertions=0;check(VECTORS.length>0,"Current native redraw vectors present");Owner last=null;
        for(String encoded:VECTORS){DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(encoded))));String name=in.readUTF();boolean real=in.readBoolean(),pixels=in.readBoolean(),realButtons=in.readBoolean(),realRestore=in.readBoolean();Map<String,int[][]> writes=new HashMap<>();for(int n=in.readInt();n>0;n--){String key=in.readUTF();int[][] rows=new int[in.readInt()][];for(int k=0;k<rows.length;k++)rows[k]=ints(in);writes.put(key,rows);}Owner owner=new Owner(snapshot(in),real,pixels,writes,realButtons,realRestore);last=owner;String error=null;for(int n=in.readInt();n>0;n--){String op=in.readUTF();int[] a=ints(in);if(error==null)try{owner.operation(op,a);}catch(IOException fail){error=fail.getMessage();}}Snapshot expected=snapshot(in);String nativeError=in.readUTF();check(nativeError.isEmpty()?error==null:error!=null,"Known-memory boundary "+name+" "+error);owner.compare(expected,name);}
        Pc1StoryControls missing=new Pc1StoryControls(last,null);last.writeInt(0xbb8458,0);missing.restoreExtra();check(true,"Inactive extra controls need no unused restore leaf");last.writeInt(0xbb8458,1);boolean rejected=false;try{missing.restoreExtra();}catch(IOException exact){rejected=exact.getMessage().contains("415d50");}check(rejected&&last.readInt(0xbb8458)==0,"Missing restore preserves already cleared native flag");last.writeInt(0x9d8a20,7);rejected=false;try{missing.draw();}catch(IOException exact){rejected=exact.getMessage().contains("40aa50");}check(rejected&&last.readInt(0x4305f4)==0x9cfc70&&last.readInt(0x9689ec)==last.readInt(0xbb8450),"Missing buttons preserves completed pointer/count switch");return assertions;
    }
    public static void main(String[] args)throws Exception{System.out.println("PC1 story controls assertions: "+run());}
